export const ZONE_BUILDING_KINDS = ['residential', 'commercial', 'industrial'] as const;
export type ZoneBuildingKind = (typeof ZONE_BUILDING_KINDS)[number];

export const PLACEABLE_KINDS = [
  'coalPlant',
  'gasPlant',
  'windTurbine',
  'waterPump',
  'well',
  'policeStation',
  'fireStation',
  'school',
  'hospital',
  'park',
  'marina',
  'airport',
  // Oasis-only placeables. A classic city never contains them; both rulesets can load them.
  'qanat',
  'cistern',
  'windbreak',
  'arcade',
  'caravanserai',
  'springHouse',
  'palm',
  // Oasis era works: one of each per city, unlocked by an era title.
  'rechargeBasin',
  'grandBazaar',
  'palaceGarden',
  // Oasis caravan routes: stops that carry commuters off the roads.
  'caravanStop',
] as const;
export type PlaceableKind = (typeof PLACEABLE_KINDS)[number];

/** Placeables that only the `oasis` ruleset offers. */
export const OASIS_PLACEABLE_KINDS = [
  'qanat',
  'cistern',
  'windbreak',
  'arcade',
  'caravanserai',
  'springHouse',
  'palm',
  'rechargeBasin',
  'grandBazaar',
  'palaceGarden',
  'caravanStop',
] as const;
export type OasisPlaceableKind = (typeof OASIS_PLACEABLE_KINDS)[number];

export function isOasisPlaceable(kind: BuildingKind): kind is OasisPlaceableKind {
  return (OASIS_PLACEABLE_KINDS as readonly string[]).includes(kind);
}

/** Era works, in the order the era titles unlock them. */
export const ERA_WORK_KINDS = ['rechargeBasin', 'grandBazaar', 'palaceGarden'] as const;
export type EraWorkKind = (typeof ERA_WORK_KINDS)[number];

export function isEraWork(kind: BuildingKind): kind is EraWorkKind {
  return (ERA_WORK_KINDS as readonly string[]).includes(kind);
}

export type BuildingKind = ZoneBuildingKind | PlaceableKind;

export type ServiceKind = 'policeStation' | 'fireStation' | 'school' | 'hospital';
export type PowerPlantKind = 'coalPlant' | 'gasPlant' | 'windTurbine';

/** Plain, serializable building state shared by the engine, the save file and the UI. */
export interface BuildingRecord {
  id: number;
  kind: BuildingKind;
  x: number;
  y: number;
  w: number;
  h: number;
  level: number;
  capacity: number;
  occupancy: number;
  condition: number;
  age: number;
  abandoned: boolean;
  emptyMonths: number;
  variant: number;
  powered: boolean;
  watered: boolean;
  /**
   * On the Oasis shade network. Absent in a classic city so the serialized building does not
   * gain a key the classic hash has never contained.
   */
  linked?: boolean;
  /** Ticks remaining while a plant is offline (blackout event). */
  offline: number;
  /** Last computed attractiveness 0..1, for diagnostics. */
  attractiveness: number;
  /** Caravan house that owns an Oasis lot, or absent for city-owned buildings. */
  owner?: number;
}

export function isZoneKind(kind: BuildingKind): kind is ZoneBuildingKind {
  return kind === 'residential' || kind === 'commercial' || kind === 'industrial';
}
